@dataclass(frozen=True)
class SeedSkill:
    """一条种子技能。``body`` 是真实 SKILL.md 的正文（逐字节）。"""

    category: str
    name: str
    description: str
    body: str
    triggers: tuple[str, ...] = ()
    #: 真实 frontmatter 声明的外部依赖（``prerequisites.commands`` / ``env_vars`` /
    #: ``dependencies``）。空 = 纯文档技能，播进来就能用。
    commands: tuple[str, ...] = ()
    env_vars: tuple[str, ...] = ()
    dependencies: tuple[str, ...] = ()
    #: 真实 frontmatter 的 ``platforms``。**不写进落盘文件**（Orbit 没有平台门控，
    #: 写了没人读），只用于报告"这条技能本来是给 macOS 的"。
    platforms: tuple[str, ...] = ()
    #: 源文件相对路径（溯源用，可据此复核）。
    source: str = ""

    @property
    def requires(self) -> dict[str, tuple[str, ...]]:
        """合并后的外部依赖视图（只保留非空项）。"""
        merged = {
            "commands": self.commands,
            "env_vars": self.env_vars,
            "dependencies": self.dependencies,
        }
        return {key: value for key, value in merged.items() if value}

    def as_dict(self) -> dict[str, Any]:
        return {
            "category": self.category,
            "name": self.name,
            "description": self.description,
            "triggers": list(self.triggers),
            "requires": {key: list(value) for key, value in self.requires.items()},
            "platforms": list(self.platforms),
            "source": self.source,
            "body_chars": len(self.body),
        }



